@file:Suppress("NOTHING_TO_INLINE")package mrpapermoon.whisper.utilsimport kotlinx.coroutines.CoroutineScopeimport kotlinx.coroutines.Deferredimport kotlinx.coroutines.asyncimport kotlinx.coroutines.runBlockingimport kotlin.coroutines.CoroutineContextimport kotlin.coroutines.EmptyCoroutineContextimport kotlin.properties.ReadOnlyPropertyimport kotlin.reflect.KPropertyinline operator fun <T> Deferred<T>.getValue(thisRef: Any?, property: KProperty<*>): T? = runBlocking { await() }fun <T> CoroutineScope.asyncProperty(	context: CoroutineContext = EmptyCoroutineContext,	block: suspend CoroutineScope.() -> T): ReadOnlyProperty<Any?, T> {	return LazyDeferred(async(context = context, block = block))}private class LazyDeferred<out T>(private val deferred: Deferred<T>) : ReadOnlyProperty<Any?, T> {	override fun getValue(thisRef: Any?, property: KProperty<*>): T = runBlocking { deferred.await() }}